const webhook = $('Booking Status Webhook').first().json;
const body = webhook.body ?? webhook;

const leads = $('Read Existing Leads').all();
const bookings = $('Read Existing Bookings').all();
const cfgJson = $('Get Business Config').first()?.json ?? null;

const bid = body.business_id ? String(body.business_id).trim() : '';

// Exact business_id match only: a lead can never be resolved against another business's config.
const config =
  cfgJson && String(cfgJson.business_id || '').trim() === bid ? cfgJson : null;

function digits(v) {
  return String(v || '').replace(/\D/g, '');
}

// Resolution order (tenant-scoped): lead_id+business_id -> phone+business_id -> email+business_id.
let lead = null;
const wantId = body.lead_id ? String(body.lead_id).trim() : '';
if (wantId) {
  lead =
    leads.find(
      (r) =>
        String(r.json.lead_id || '').trim() === wantId &&
        String(r.json.business_id || '').trim() === bid
    ) || null;
}
if (!lead && body.phone) {
  const p = digits(body.phone);
  if (p) {
    lead =
      leads.find(
        (r) => digits(r.json.phone) === p && String(r.json.business_id || '').trim() === bid
      ) || null;
  }
}
if (!lead && body.email) {
  const e = String(body.email).trim().toLowerCase();
  if (e) {
    lead =
      leads.find(
        (r) =>
          String(r.json.email || '').trim().toLowerCase() === e &&
          String(r.json.business_id || '').trim() === bid
      ) || null;
  }
}

// Idempotent replay detection: same booking_id within the same business already recorded?
const incomingBookingId = body.booking_id ? String(body.booking_id).trim() : '';
const duplicateBooking = !!(
  incomingBookingId &&
  bookings.some(
    (r) =>
      String(r.json.booking_id || '').trim() === incomingBookingId &&
      String(r.json.business_id || '').trim() === bid
  )
);

const booking = {
  booking_id:
    incomingBookingId || 'bk_' + Date.now() + '_' + Math.random().toString(36).slice(2, 10),
  lead_id: lead ? String(lead.json.lead_id || '') : wantId,
  business_id: bid,
  created_at: new Date().toISOString(),
  booking_at: body.booking_at ? String(body.booking_at) : new Date().toISOString(),
  source: body.source ? String(body.source) : 'booking_provider',
  status: body.status ? String(body.status) : 'confirmed'
};

function esc(v) {
  return String(v == null ? '' : v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

return [
  {
    json: {
      _leadFound: !!lead,
      _configFound: !!config,
      _duplicateBooking: duplicateBooking,
      lead: lead ? lead.json : null,
      booking: booking,
      business_name: config ? config.business_name || '' : '',
      owner_email: config ? config.owner_email || '' : '',
      reply_to_email: config ? config.reply_to_email || '' : '',
      from_email: config ? config.from_email || '' : '',
      _esc_lead_id: esc(booking.lead_id),
      _esc_booking_id: esc(booking.booking_id),
      _esc_business_name: esc(config ? config.business_name || '' : ''),
      _esc_name: lead ? esc(lead.json.name) : '',
      _esc_phone: lead ? esc(lead.json.phone) : '',
      _esc_service: lead ? esc(lead.json.service) : '',
      _esc_booking_at: esc(booking.booking_at),
      _esc_booking_link: lead ? esc(lead.json.booking_link) : ''
    }
  }
];

const r = $('Resolve Lead & Booking').first().json;
const b = r.booking || {};
return [
  {
    json: {
      booking_id: b.booking_id,
      lead_id: b.lead_id,
      business_id: b.business_id,
      created_at: b.created_at,
      booking_at: b.booking_at,
      source: b.source,
      status: b.status
    }
  }
];

const r = $('Resolve Lead & Booking').first().json;
const lead = r.lead || {};
const b = r.booking || {};
const now = new Date().toISOString();

// Prefer the stable webhook lead_id when supplied; fall back to the resolved lead.
const webhook = $('Booking Status Webhook').first().json;
const body = webhook.body ?? webhook;
const whLeadId = body.lead_id ? String(body.lead_id).trim() : '';
const matchLeadId = whLeadId || String(lead.lead_id || b.lead_id || '');

return [
  {
    json: Object.assign({}, lead, {
      lead_id: matchLeadId,
      booked: 'TRUE',
      booked_at: b.booking_at,
      booking_id: b.booking_id,
      status: 'booked',
      next_followup_at: '',
      updated_at: now,
      booking_link: lead.booking_link || '',
      business_name: r.business_name,
      owner_email: r.owner_email,
      from_email: r.from_email,
      reply_to_email: r.reply_to_email,
      _esc_lead_id: r._esc_lead_id,
      _esc_booking_id: r._esc_booking_id,
      _esc_business_name: r._esc_business_name,
      _esc_name: r._esc_name,
      _esc_phone: r._esc_phone,
      _esc_service: r._esc_service,
      _esc_booking_at: r._esc_booking_at,
      _esc_booking_link: r._esc_booking_link
    })
  }
];
